[ -z "$SERVICE" ] && { echo "Usage: b00t pm stop <service>"; exit 1; }
[ -z "$SERVICE" ] && { echo "Usage: b00t pm restart <service>"; exit 1; }

--dry-run: print actions, don't execute
--reset: clear soul install.* keys and re-detect
--dry-run: DRY_RUN=true ;;
--reset: RESET=true ;;
--mode: FORCE_MODE="${arg#--mode=}" ;;
--mode: shift; FORCE_MODE="${1:-}" ;;
